-- An inbox this dashboard created in the user's Cloudflare account.
-- The owner token is stored only as a SHA-256 hash. Append-only: do not edit this file.
CREATE TABLE IF NOT EXISTS cloudflare_inbox (
  "userId" TEXT NOT NULL PRIMARY KEY REFERENCES "user" ("id") ON DELETE CASCADE,
  cf_account_id TEXT NOT NULL,
  worker_name TEXT NOT NULL,
  d1_name TEXT NOT NULL,
  d1_id TEXT,
  public_url TEXT,
  owner_token_hash TEXT,
  host TEXT NOT NULL,
  hostname TEXT,
  status TEXT NOT NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
